      ProtectionClass('encryptedAtRest');
  static const ProtectionClass enclave = ProtectionClass('enclave');
  static const ProtectionClass hardwareModule =
      ProtectionClass('hardwareModule');
  static const ProtectionClass externalCustodian =
      ProtectionClass('externalCustodian');

  /// Every value this specification's schema permits.
  static const List<ProtectionClass> values = <ProtectionClass>[
    software,
    encryptedAtRest,
    enclave,
    hardwareModule,
    externalCustodian
  ];
}

/// How a key is held. Present only in the custody projection. Carries no key material,
/// and a conforming VTA MUST NOT place any in `ext`.
class RoleKeyCustody {
  const RoleKeyCustody({
    this.keyId,
    this.origin,
    required this.exportable,
    required this.neverExportable,
    required this.inBackups,
    required this.protection,
    this.boundary,
    this.destroyed,
  });

  /// Read this payload from a decoded JSON object.
  factory RoleKeyCustody.fromJson(Map<String, dynamic> json) => RoleKeyCustody(
        keyId: json['keyId'] as String?,
        origin:
            json['origin'] == null ? null : KeyOrigin(json['origin'] as String),
        exportable: json['exportable'] as bool,
        neverExportable: json['neverExportable'] as bool,
        inBackups: json['inBackups'] as bool,
        protection: ProtectionClass(json['protection'] as String),
        boundary: json['boundary'] as String?,
        destroyed: json['destroyed'] as bool?,
      );

  /// The custodian record identifier (`keys/*`'s `keyId`) behind this key. Absent for a
  /// key this VTA does not hold (`protection: externalCustodian`).
  final String? keyId;
  final KeyOrigin? origin;

  /// Whether the custodian would release the private half. Always `false` for
  /// `attestation` and `update` keys. Stated explicitly, never absent.
  final bool exportable;

  /// True when no authority can make the key exportable. `true` implies `exportable:
  /// false`.
  final bool neverExportable;

  /// Whether the key, or material it can be re-derived or decrypted from, is in the
  /// VTA's backups or any state transfer. Always `false` for `attestation` and `update`
  /// keys (VTI-KEY-112).
  final bool inBackups;
  final ProtectionClass protection;

  /// Opaque, VTA-assigned label of the protection boundary holding the key
  /// (CONVENTIONS.md §5.2). Two keys with the same label are lost or compromised
  /// together. A recovery update key MUST carry a label different from every routine
  /// update key's. Custody projection only; never published.
  final String? boundary;

  /// True once the private half has been destroyed — a retired `attestation` or
  /// `messaging` key. The record survives so the key's past signatures stay
  /// attributable.
  final bool? destroyed;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        if (keyId != null) 'keyId': keyId!,
        if (origin != null) 'origin': origin!.value,
        'exportable': exportable,
        'neverExportable': neverExportable,
        'inBackups': inBackups,
        'protection': protection.value,
        if (boundary != null) 'boundary': boundary!,
        if (destroyed != null) 'destroyed': destroyed!,
      };
}

/// Vendor-namespaced extension object per SPEC.md §4.5.1. Each immediate key MUST be a
/// reverse-DNS namespace; structure under each namespace is opaque to the framework.
typedef Ext = Map<String, dynamic>;

/// One key in one role. A key is in exactly one role for its whole life; a change of
/// role is a retirement from one and an addition to another, with fresh material under
/// a fresh identifier.
class RoleKey {
  const RoleKey({
    this.verificationMethod,
    required this.role,
    this.updateKeyClass,
    this.relationships,
    required this.keyType,
    this.publicKeyMultibase,
    this.commitment,
    required this.state,
    this.publishedInVersionId,
    this.removedInVersionId,
    this.activatesAt,
    this.retireAfter,
    this.compromisedSince,
    this.rotationId,
    this.label,
    this.custody,
    this.ext,
  });

  /// Read this payload from a decoded JSON object.
  factory RoleKey.fromJson(Map<String, dynamic> json) => RoleKey(
        verificationMethod: json['verificationMethod'] as String?,
        role: KeyRole(json['role'] as String),
        updateKeyClass: json['updateKeyClass'] == null
            ? null
            : UpdateKeyClass(json['updateKeyClass'] as String),
        relationships: json['relationships'] == null
            ? null
            : (json['relationships'] as List<dynamic>)
                .map((e) => DidVerificationRelationship(e as String))
                .toList(),
        keyType: KeyType(json['keyType'] as String),
        publicKeyMultibase: json['publicKeyMultibase'] as String?,
        commitment: json['commitment'] as String?,
        state: RoleKeyState(json['state'] as String),
        publishedInVersionId: json['publishedInVersionId'] as String?,
        removedInVersionId: json['removedInVersionId'] as String?,
        activatesAt: json['activatesAt'] as String?,
        retireAfter: json['retireAfter'] as String?,
        compromisedSince: json['compromisedSince'] as String?,
        rotationId: json['rotationId'] as String?,
        label: json['label'] as String?,
        custody: json['custody'] == null
            ? null
            : RoleKeyCustody.fromJson(json['custody'] as Map<String, dynamic>),
        ext: json['ext'] as Map<String, dynamic>?,
      );

  /// The full verification-method identifier (`did#fragment`) the document publishes the
  /// key under and lists in `keyRoles`. Absent for `update` keys, which are never
  /// role-bound verification methods (VTI-KEY-093). A VTA minting a method SHOULD derive
  /// its fragment from the key (VTI-KEY-150).
  final String? verificationMethod;
  final KeyRole role;
  final UpdateKeyClass? updateKeyClass;

  /// The relationships the key is (or, while `pending`, will be) listed in: always
  /// exactly its role's one relationship. Empty for `update`, `retired` and `revoked`
  /// keys.
  final List<DidVerificationRelationship>? relationships;
  final KeyType keyType;

  /// The public half, multibase-encoded, exactly as published. Absent for a `committed`
  /// update key, whose public half the identifier has not yet revealed.
  final String? publicKeyMultibase;

  /// For a `committed` update key: the commitment the identifier publishes (a did:webvh
  /// `nextKeyHashes` entry, a KERI next-key digest), in the method's own encoding.
  final String? commitment;
  final RoleKeyState state;

  /// The method's version identifier of the change that first published the key or its
  /// commitment (method-profiles/: a did:webvh `versionId`, a KERI event's sequence
  /// number and digest). Absent while `pending`.
  final String? publishedInVersionId;

  /// Version identifier of the change that retired or revoked the key.
  final String? removedInVersionId;

  /// For a `staged` key: when the VTA will begin using it — no earlier than the
  /// publishing change's cache horizon.
  final String? activatesAt;

  /// For a `retiring` key: the end of its overlap. Custody projection only.
  final String? retireAfter;

  /// For a `revoked` key: the compromise time (VTI-KEY-121), published as the
  /// verification method's `revoked` value. Where it cannot be established, the time the
  /// key was first published.
  final String? compromisedSince;

  /// The rotation this key was introduced or retired by.
  final String? rotationId;

  /// Operator-facing label. Custody projection only.
  final String? label;
  final RoleKeyCustody? custody;
  final Ext? ext;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        if (verificationMethod != null)
          'verificationMethod': verificationMethod!,
        'role': role.value,
        if (updateKeyClass != null) 'updateKeyClass': updateKeyClass!.value,
        if (relationships != null)
          'relationships': relationships!.map((e) => e.value).toList(),
        'keyType': keyType.value,
        if (publicKeyMultibase != null)
          'publicKeyMultibase': publicKeyMultibase!,
        if (commitment != null) 'commitment': commitment!,
        'state': state.value,
        if (publishedInVersionId != null)
          'publishedInVersionId': publishedInVersionId!,
        if (removedInVersionId != null)
          'removedInVersionId': removedInVersionId!,
        if (activatesAt != null) 'activatesAt': activatesAt!,
        if (retireAfter != null) 'retireAfter': retireAfter!,
        if (compromisedSince != null) 'compromisedSince': compromisedSince!,
        if (rotationId != null) 'rotationId': rotationId!,
        if (label != null) 'label': label!,
        if (custody != null) 'custody': custody!.toJson(),
        if (ext != null) 'ext': ext!,
      };
}

/// `planned` — a successor was staged, activated, and the predecessor retired on the
/// operator's schedule. `compromise` — a key was revoked and, where the role would
/// otherwise be empty, replaced in the same change. `addition` — a key joined a role
/// without anything leaving it. `recovery` — the identifier's update authority moved
/// to the committed recovery key, because the VTA's own update keys were lost or may
/// be in someone else's hands.
///
/// An extension type rather than an enum: a value from a newer MINOR of this
/// specification must not crash the parse (SPEC §5.2), and an enum would throw on one.
/// Compare against the constants below, and treat anything else as unrecognised.
extension type const RotationKind(String value) {
  static const RotationKind planned = RotationKind('planned');
  static const RotationKind compromise = RotationKind('compromise');
  static const RotationKind addition = RotationKind('addition');
  static const RotationKind recovery = RotationKind('recovery');

  /// Every value this specification's schema permits.
  static const List<RotationKind> values = <RotationKind>[
    planned,
    compromise,
    addition,
    recovery
  ];
}

/// `pendingApproval` — awaiting the approvals the VTA's policy requires; nothing is
/// published. `awaitingRecoveryProof` — approved, and waiting for the recovery
/// custodian's proof over the change; nothing is published. `staged` — successor
/// published, not yet used. `overlapping` — successor active, predecessor `retiring`.
/// `completed` — every predecessor retired, or the change is published and any overlap
/// it began has ended. `aborted` — the successor was retired instead of the
/// predecessor, or a revocation superseded the change. `expired` — the approvals or
/// the recovery proof did not arrive before the preview expired; nothing was
/// published.
///
/// An extension type rather than an enum: a value from a newer MINOR of this
/// specification must not crash the parse (SPEC §5.2), and an enum would throw on one.
/// Compare against the constants below, and treat anything else as unrecognised.
extension type const RotationState(String value) {
  static const RotationState pendingApproval = RotationState('pendingApproval');
  static const RotationState awaitingRecoveryProof =
      RotationState('awaitingRecoveryProof');
  static const RotationState staged = RotationState('staged');
  static const RotationState overlapping = RotationState('overlapping');
  static const RotationState completed = RotationState('completed');
  static const RotationState aborted = RotationState('aborted');
  static const RotationState expired = RotationState('expired');

  /// Every value this specification's schema permits.
  static const List<RotationState> values = <RotationState>[
    pendingApproval,
    awaitingRecoveryProof,
    staged,
    overlapping,
    completed,
    aborted,
    expired
  ];
}

/// One change to a role's key set, from preview to completion. The identifier's
/// history is the authority for what was published; this record adds which change was
/// which and, in the custody projection, who asked, who approved, and why.
class RotationRecord {
  const RotationRecord({
    required this.rotationId,
    required this.role,
    required this.kind,
    required this.state,
    this.predecessors,
    this.successors,
    this.startedInVersionId,
    this.endedInVersionId,
    this.startedAt,
    this.cacheHorizonAt,
    this.activatesAt,
    this.overlapUntil,
    this.autoRetire,
    this.endedAt,
    this.initiatedBy,
    this.approvals,
    this.reason,
    this.ext,
  });

  /// Read this payload from a decoded JSON object.
  factory RotationRecord.fromJson(Map<String, dynamic> json) => RotationRecord(
        rotationId: json['rotationId'] as String,
        role: KeyRole(json['role'] as String),
        kind: RotationKind(json['kind'] as String),
        state: RotationState(json['state'] as String),
        predecessors: json['predecessors'] == null
            ? null
            : (json['predecessors'] as List<dynamic>)
                .map((e) => e as String)
                .toList(),
        successors: json['successors'] == null
            ? null
            : (json['successors'] as List<dynamic>)
                .map((e) => e as String)
                .toList(),
        startedInVersionId: json['startedInVersionId'] as String?,
        endedInVersionId: json['endedInVersionId'] as String?,
        startedAt: json['startedAt'] as String?,
        cacheHorizonAt: json['cacheHorizonAt'] as String?,
        activatesAt: json['activatesAt'] as String?,
        overlapUntil: json['overlapUntil'] as String?,
        autoRetire: json['autoRetire'] as bool?,
        endedAt: json['endedAt'] as String?,
        initiatedBy: json['initiatedBy'] as String?,
        approvals: json['approvals'] == null
            ? null
            : KeyRoleApprovalState.fromJson(
                json['approvals'] as Map<String, dynamic>),
        reason: json['reason'] as String?,
        ext: json['ext'] as Map<String, dynamic>?,
      );

  final String rotationId;
  final KeyRole role;
  final RotationKind kind;
  final RotationState state;

  /// Verification-method identifiers (for `update`, public keys or commitments) leaving
  /// the role.
  final List<String>? predecessors;

  /// Verification-method identifiers (for `update`, public keys or commitments) entering
  /// the role.
  final List<String>? successors;
  final String? startedInVersionId;
  final String? endedInVersionId;
  final String? startedAt;

  /// Planned rotations: the publishing change's cache horizon (CONVENTIONS.md §10.1).
  /// The switch and any retirement happen no earlier.
  final String? cacheHorizonAt;

  /// When the successor becomes `active` and the predecessor `retiring`; never before
  /// `cacheHorizonAt`.
  final String? activatesAt;

  /// Custody projection only. End of the overlap.
  final String? overlapUntil;

  /// Custody projection only. Whether the VTA retires the predecessor itself at
  /// `overlapUntil`.
  final bool? autoRetire;
  final String? endedAt;

  /// Custody projection only. VID of the administrator whose signed request started the
  /// change.
  final String? initiatedBy;
  final KeyRoleApprovalState? approvals;

  /// Custody projection only. The operator's stated reason. Never published.
  final String? reason;
  final Ext? ext;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'rotationId': rotationId,
        'role': role.value,
        'kind': kind.value,
        'state': state.value,
        if (predecessors != null) 'predecessors': predecessors!,
        if (successors != null) 'successors': successors!,
        if (startedInVersionId != null)
          'startedInVersionId': startedInVersionId!,
        if (endedInVersionId != null) 'endedInVersionId': endedInVersionId!,
        if (startedAt != null) 'startedAt': startedAt!,
        if (cacheHorizonAt != null) 'cacheHorizonAt': cacheHorizonAt!,
        if (activatesAt != null) 'activatesAt': activatesAt!,
        if (overlapUntil != null) 'overlapUntil': overlapUntil!,
        if (autoRetire != null) 'autoRetire': autoRetire!,
        if (endedAt != null) 'endedAt': endedAt!,
        if (initiatedBy != null) 'initiatedBy': initiatedBy!,
        if (approvals != null) 'approvals': approvals!.toJson(),
        if (reason != null) 'reason': reason!,
        if (ext != null) 'ext': ext!,
      };
}

/// A file the identifier's method publishes, as the method profile names it
/// (`did.jsonl` for did:webvh, `did.json` and `keri.cesr` for did:webs).
class PublishedArtifact {
  const PublishedArtifact({
    required this.name,
    required this.mediaType,
    required this.content,
  });

  /// Read this payload from a decoded JSON object.
  factory PublishedArtifact.fromJson(Map<String, dynamic> json) =>
      PublishedArtifact(
        name: json['name'] as String,
        mediaType: json['mediaType'] as String,
        content: json['content'] as String,
      );

  final String name;
  final String mediaType;

  /// The artefact's content, or for an append-only artefact the appended part, as text.
  final String content;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'name': name,
        'mediaType': mediaType,
        'content': content,
      };
}

/// How the change reaches resolvers.
class Publication {
  const Publication({
    required this.selfPublish,
    this.artifacts,
  });

  /// Read this payload from a decoded JSON object.
  factory Publication.fromJson(Map<String, dynamic> json) => Publication(
        selfPublish: json['selfPublish'] as bool,
        artifacts: json['artifacts'] == null
            ? null
            : (json['artifacts'] as List<dynamic>)
                .map((e) =>
                    PublishedArtifact.fromJson(e as Map<String, dynamic>))
                .toList(),
      );

  /// True when no hosting service holds the identifier for the VTA: the caller must
  /// publish `artifacts`, and until it does resolvers see the previous version.
  final bool selfPublish;

  /// Present when `selfPublish` is true.
  final List<PublishedArtifact>? artifacts;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'selfPublish': selfPublish,
        if (artifacts != null)
          'artifacts': artifacts!.map((e) => e.toJson()).toList(),
      };
}

/// VTA DIDs — Create — response payload
class Response {
  const Response({
    required this.did,
    required this.outcome,
    this.preview,
    this.approvals,
    this.newVersionId,
    this.keys,
    this.rotation,
    this.publication,
    this.contextId,
    this.method,
    this.ext,
  });

  /// Read this payload from a decoded JSON object.
  factory Response.fromJson(Map<String, dynamic> json) => Response(
        did: json['did'] as String,
        outcome: KeyRoleChangeOutcome(json['outcome'] as String),
        preview: json['preview'] == null
            ? null
            : DidDocumentPreview.fromJson(
                json['preview'] as Map<String, dynamic>),
        approvals: json['approvals'] == null
            ? null
            : KeyRoleApprovalState.fromJson(
                json['approvals'] as Map<String, dynamic>),
        newVersionId: json['newVersionId'] as String?,
        keys: json['keys'] == null
            ? null
            : (json['keys'] as List<dynamic>)
                .map((e) => RoleKey.fromJson(e as Map<String, dynamic>))
                .toList(),
        rotation: json['rotation'] == null
            ? null
            : RotationRecord.fromJson(json['rotation'] as Map<String, dynamic>),
        publication: json['publication'] == null
            ? null
            : Publication.fromJson(json['publication'] as Map<String, dynamic>),
        contextId: json['contextId'] as String?,
        method: json['method'] as String?,
        ext: json['ext'] as Map<String, dynamic>?,
      );

  final String did;
  final KeyRoleChangeOutcome outcome;

  /// Present when `outcome` is `preview`, `pendingApproval` or `awaitingRecoveryProof`:
  /// the plan, and what an approval is bound to.
  final DidDocumentPreview? preview;

  /// Present when `outcome` is `pendingApproval`.
  final KeyRoleApprovalState? approvals;

  /// Present when `outcome` is `applied`: the version identifier of the change. Pass it
  /// as the next change's `expectedVersionId`.
  final String? newVersionId;

  /// Every key whose state this change sets or would set, after the change.
  final List<RoleKey>? keys;
  final RotationRecord? rotation;

  /// Present when `outcome` is `applied`.
  final Publication? publication;
  final String? contextId;
  final DidMethodName? method;
  final Ext? ext;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'did': did,
        'outcome': outcome.value,
        if (preview != null) 'preview': preview!.toJson(),
        if (approvals != null) 'approvals': approvals!.toJson(),
        if (newVersionId != null) 'newVersionId': newVersionId!,
        if (keys != null) 'keys': keys!.map((e) => e.toJson()).toList(),
        if (rotation != null) 'rotation': rotation!.toJson(),
        if (publication != null) 'publication': publication!.toJson(),
        if (contextId != null) 'contextId': contextId!,
        if (method != null) 'method': method!,
        if (ext != null) 'ext': ext!,
      };
}

/// A recovery key offered for commitment (CONVENTIONS.md §5.3). The VTA computes the
/// method's commitment from it, verifies `proofOfPossession`, and then keeps only the
/// commitment. The key MUST be held by a custodian in a protection boundary other than
/// the VTA's; a VTA MUST refuse one it generated or can derive
/// (`vta/dids:recoveryCommitmentRequired`).
class RecoveryCommitment {
  const RecoveryCommitment({
    required this.keyType,
    required this.publicKeyMultibase,
    this.proofOfPossession,
    this.label,
  });

  /// Read this payload from a decoded JSON object.
  factory RecoveryCommitment.fromJson(Map<String, dynamic> json) =>
      RecoveryCommitment(
        keyType: KeyType(json['keyType'] as String),
        publicKeyMultibase: json['publicKeyMultibase'] as String,
        proofOfPossession: json['proofOfPossession'] as String?,
        label: json['label'] as String?,
      );

  final KeyType keyType;

  /// The recovery key's public half. Not published by the VTA where the method commits
  /// by hash.
  final String publicKeyMultibase;

  /// Multibase signature by the recovery key over the UTF-8 bytes of
  /// `vta-dids-recovery-commitment/v1`, a zero byte, and the request's `previewId`.
  /// Absent on a dry run, which is how the `previewId` is obtained; REQUIRED on the
  /// apply request, and the only member besides `previewId`, `dryRun` and
  /// `recoveryProof` that may differ between the two.
  final String? proofOfPossession;

  /// Operator-facing name of the custodian. Custody projection only; never published.
  final String? label;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'keyType': keyType.value,
        'publicKeyMultibase': publicKeyMultibase,
        if (proofOfPossession != null) 'proofOfPossession': proofOfPossession!,
        if (label != null) 'label': label!,
      };
}

/// Ask a Verifiable Trust Agent to create a key-role identity under an eligible DID
/// method, from a key-role DID template. The VTA mints every key fresh by its role's
/// custody rules and commits a routine update successor and the caller's recovery key
/// (CONVENTIONS.md §4, §5). No caller-supplied key, key identifier, keyed document or
/// existing history is accepted.
class Payload {
  const Payload({
    required this.contextId,
    required this.method,
    required this.template,
    this.templateContext,
    this.templateVars,
    this.methodParameters,
    required this.recoveryCommitment,
    this.label,
    this.dryRun,
    this.previewId,
    this.reason,
    this.ext,
  });

  /// Read this payload from a decoded JSON object.
  factory Payload.fromJson(Map<String, dynamic> json) => Payload(
        contextId: json['contextId'] as String,
        method: json['method'] as String,
        template: json['template'] as String,
        templateContext: json['templateContext'] as String?,
        templateVars: json['templateVars'] as Map<String, dynamic>?,
        methodParameters: json['methodParameters'] as Map<String, dynamic>?,
        recoveryCommitment: RecoveryCommitment.fromJson(
            json['recoveryCommitment'] as Map<String, dynamic>),
        label: json['label'] as String?,
        dryRun: json['dryRun'] as bool?,
        previewId: json['previewId'] as String?,
        reason: json['reason'] as String?,
        ext: json['ext'] as Map<String, dynamic>?,
      );

  /// Context the identity belongs to. Its derived keys are derived under this context's
  /// base.
  final String contextId;
  final DidMethodName method;

  /// A key-role DID template (`schemaVersion` 3; CONVENTIONS.md §4). Its `keyRoles`
  /// layout fixes which keys are minted; its `document` supplies only non-key members.
  final String template;

  /// Context whose templates `template` is resolved against. Absent uses the global
  /// scope.
  final String? templateContext;

  /// Values for the template's variables, checked against its `requiredVars` and
  /// `optionalVars` by the VTA's renderer.
  final Map<String, dynamic>? templateVars;

  /// Validated against the method profile's `CreateParameters` schema
  /// (method-profiles/&lt;method&gt;.schema.json); a member it does not define is refused with
  /// `vta/dids:methodParameterUnsupported`.
  final Map<String, dynamic>? methodParameters;
  final RecoveryCommitment recoveryCommitment;

  /// Operator-facing label. Never published.
  final String? label;

  /// Compute and return the preview without writing anything but the plan
  /// (CONVENTIONS.md §6.1). Absent reads as false.
  final bool? dryRun;

  /// Apply exactly the plan a previous dry run of this same request returned, or nothing
  /// (CONVENTIONS.md §6.1); what every approval is bound to.
  final String? previewId;

  /// Why the change is being made, for the audit trail and for the other approvers.
  /// Never published.
  final String? reason;
  final Ext? ext;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'contextId': contextId,
        'method': method,
        'template': template,
        if (templateContext != null) 'templateContext': templateContext!,
        if (templateVars != null) 'templateVars': templateVars!,
        if (methodParameters != null) 'methodParameters': methodParameters!,
        'recoveryCommitment': recoveryCommitment.toJson(),
        if (label != null) 'label': label!,
        if (dryRun != null) 'dryRun': dryRun!,
        if (previewId != null) 'previewId': previewId!,
        if (reason != null) 'reason': reason!,
        if (ext != null) 'ext': ext!,
      };
}

/// Why this specification version is deprecated, or null when it is current.
///
/// Set when the version is retired, or superseded by a later version of the
/// same slug at an equal or higher maturity (SPEC "Superseded and Withdrawn
/// Versions"). A deprecated version is still supported; it is removed from
/// this package once withdrawn.
const String? deprecation = null;

/// The Trust Task type URI this library's [Payload] is carried under.
const String typeUri = 'https://trusttasks.org/spec/vta/dids/create/1.0';

/// The `MAJOR.MINOR` this version declares it extends (SPEC §5.2, "Declared
/// extension"), or null when it declares none.
///
/// Only the direct declaration. A consumer implementing that version SHOULD
/// accept a document of this one by ignoring the payload members it does not
/// recognise; [readForVersion] does that, walking the whole chain through
/// `package:trust_tasks/specs/extends_index.dart`. Named `extendsVersion`
/// because `extends` is a reserved word.
const String? extendsVersion = null;

/// The success-response form of [typeUri] (SPEC §4.4.1).
const String responseTypeUri =
    'https://trusttasks.org/spec/vta/dids/create/1.0#response';

/// This specification's payload schema, as JSON text.
///
/// SPEC §7.2 item 2 is performed against this. It ships with the library rather
/// than only as a file under specs/ because a Dart class carries none of the
/// schema's constraints — not minLength, not pattern, not the oneOf mutual
/// exclusion — so without it every such rule is unenforced. Cross-file \$refs are
/// already inlined, so it needs no resolver.
const String payloadSchemaJson =
    '{"\$schema":"https://json-schema.org/draft/2020-12/schema","\$id":"https://trusttasks.org/spec/vta/dids/create/1.0","title":"VTA DIDs — Create — payload","description":"Ask a Verifiable Trust Agent to create a key-role identity under an eligible DID method, from a key-role DID template. The VTA mints every key fresh by its role\'s custody rules and commits a routine update successor and the caller\'s recovery key (CONVENTIONS.md §4, §5). No caller-supplied key, key identifier, keyed document or existing history is accepted.","type":"object","additionalProperties":false,"required":["contextId","method","template","recoveryCommitment"],"properties":{"contextId":{"type":"string","minLength":1,"description":"Context the identity belongs to. Its derived keys are derived under this context\'s base."},"method":{"\$ref":"#/\$defs/DidMethodName"},"template":{"type":"string","minLength":1,"description":"A key-role DID template (`schemaVersion` 3; CONVENTIONS.md §4). Its `keyRoles` layout fixes which keys are minted; its `document` supplies only non-key members."},"templateContext":{"type":"string","minLength":1,"description":"Context whose templates `template` is resolved against. Absent uses the global scope."},"templateVars":{"type":"object","additionalProperties":true,"description":"Values for the template\'s variables, checked against its `requiredVars` and `optionalVars` by the VTA\'s renderer."},"methodParameters":{"type":"object","description":"Validated against the method profile\'s `CreateParameters` schema (method-profiles/<method>.schema.json); a member it does not define is refused with `vta/dids:methodParameterUnsupported`."},"recoveryCommitment":{"\$ref":"#/\$defs/RecoveryCommitment"},"label":{"type":"string","maxLength":256,"description":"Operator-facing label. Never published."},"dryRun":{"type":"boolean","description":"Compute and return the preview without writing anything but the plan (CONVENTIONS.md §6.1). Absent reads as false."},"previewId":{"type":"string","minLength":16,"description":"Apply exactly the plan a previous dry run of this same request returned, or nothing (CONVENTIONS.md §6.1); what every approval is bound to."},"reason":{"type":"string","maxLength":1024,"description":"Why the change is being made, for the audit trail and for the other approvers. Never published."},"ext":{"\$ref":"#/\$defs/Ext"}},"\$defs":{"Response":{"\$anchor":"response","title":"VTA DIDs — Create — response payload","type":"object","additionalProperties":false,"required":["did","outcome"],"properties":{"did":{"type":"string","minLength":1},"outcome":{"\$ref":"#/\$defs/KeyRoleChangeOutcome"},"preview":{"\$ref":"#/\$defs/DidDocumentPreview","description":"Present when `outcome` is `preview`, `pendingApproval` or `awaitingRecoveryProof`: the plan, and what an approval is bound to."},"approvals":{"\$ref":"#/\$defs/KeyRoleApprovalState","description":"Present when `outcome` is `pendingApproval`."},"newVersionId":{"type":"string","description":"Present when `outcome` is `applied`: the version identifier of the change. Pass it as the next change\'s `expectedVersionId`."},"keys":{"type":"array","items":{"\$ref":"#/\$defs/RoleKey"},"description":"Every key whose state this change sets or would set, after the change."},"rotation":{"\$ref":"#/\$defs/RotationRecord"},"publication":{"\$ref":"#/\$defs/Publication","description":"Present when `outcome` is `applied`."},"contextId":{"type":"string"},"method":{"\$ref":"#/\$defs/DidMethodName"},"ext":{"\$ref":"#/\$defs/Ext"}}},"Ext":{"title":"Ext","description":"Vendor-namespaced extension object per SPEC.md §4.5.1. Each immediate key MUST be a reverse-DNS namespace; structure under each namespace is opaque to the framework.","type":"object","minProperties":1,"additionalProperties":true,"propertyNames":{"pattern":"^[a-z][a-z0-9-]*(\\\\.[a-z0-9-]+)+\$"}},"DidMethodName":{"title":"DidMethodName","type":"string","pattern":"^[a-z0-9]+(:[a-z0-9]+)*\$","description":"The DID method an identity uses, as the method profile that governs it is named: `webvh` for a did:webvh identity, `scid:vh` for the did:scid:vh:1 form of one, `webs` for did:webs. Deliberately a pattern and not an enumeration: a method is added by publishing its profile under method-profiles/, never by changing this schema. A VTA MUST refuse a method it holds no profile for, or whose profile declares it ineligible, with `vta/dids:methodNotEligible`."},"Publication":{"title":"Publication","type":"object","additionalProperties":false,"required":["selfPublish"],"description":"How the change reaches resolvers.","properties":{"selfPublish":{"type":"boolean","description":"True when no hosting service holds the identifier for the VTA: the caller must publish `artifacts`, and until it does resolvers see the previous version."},"artifacts":{"type":"array","items":{"\$ref":"#/\$defs/PublishedArtifact"},"description":"Present when `selfPublish` is true."}}},"PublishedArtifact":{"title":"PublishedArtifact","type":"object","additionalProperties":false,"required":["name","mediaType","content"],"description":"A file the identifier\'s method publishes, as the method profile names it (`did.jsonl` for did:webvh, `did.json` and `keri.cesr` for did:webs).","properties":{"name":{"type":"string","minLength":1,"maxLength":128},"mediaType":{"type":"string","minLength":1},"content":{"type":"string","description":"The artefact\'s content, or for an append-only artefact the appended part, as text."}}},"RotationRecord":{"title":"RotationRecord","type":"object","additionalProperties":false,"required":["rotationId","role","kind","state"],"description":"One change to a role\'s key set, from preview to completion. The identifier\'s history is the authority for what was published; this record adds which change was which and, in the custody projection, who asked, who approved, and why.","properties":{"rotationId":{"type":"string","minLength":1},"role":{"\$ref":"#/\$defs/KeyRole"},"kind":{"\$ref":"#/\$defs/RotationKind"},"state":{"\$ref":"#/\$defs/RotationState"},"predecessors":{"type":"array","items":{"type":"string"},"description":"Verification-method identifiers (for `update`, public keys or commitments) leaving the role."},"successors":{"type":"array","items":{"type":"string"},"description":"Verification-method identifiers (for `update`, public keys or commitments) entering the role."},"startedInVersionId":{"type":"string"},"endedInVersionId":{"type":"string"},"startedAt":{"type":"string","format":"date-time"},"cacheHorizonAt":{"type":"string","format":"date-time","description":"Planned rotations: the publishing change\'s cache horizon (CONVENTIONS.md §10.1). The switch and any retirement happen no earlier."},"activatesAt":{"type":"string","format":"date-time","description":"When the successor becomes `active` and the predecessor `retiring`; never before `cacheHorizonAt`."},"overlapUntil":{"type":"string","format":"date-time","description":"Custody projection only. End of the overlap."},"autoRetire":{"type":"boolean","description":"Custody projection only. Whether the VTA retires the predecessor itself at `overlapUntil`."},"endedAt":{"type":"string","format":"date-time"},"initiatedBy":{"type":"string","description":"Custody projection only. VID of the administrator whose signed request started the change."},"approvals":{"\$ref":"#/\$defs/KeyRoleApprovalState"},"reason":{"type":"string","maxLength":1024,"description":"Custody projection only. The operator\'s stated reason. Never published."},"ext":{"\$ref":"#/\$defs/Ext"}}},"KeyRoleApprovalState":{"title":"KeyRoleApprovalState","type":"object","additionalProperties":false,"required":["required","received","expiresAt"],"description":"Approval progress of a change the VTA\'s policy gates on approvals (CONVENTIONS.md §6).","properties":{"required":{"type":"integer","minimum":1,"description":"Distinct approvals the VTA\'s policy requires."},"received":{"type":"integer","minimum":0,"description":"Distinct approvals recorded so far, the initiator\'s own included."},"approvals":{"type":"array","items":{"\$ref":"#/\$defs/RecordedApproval"},"description":"The approvals recorded. Custody projection only; omitted from a response to anyone who is not themselves an eligible approver of this change."},"expiresAt":{"type":"string","format":"date-time","description":"When the preview, and every approval bound to it, stops being usable."}}},"RecordedApproval":{"title":"RecordedApproval","type":"object","additionalProperties":false,"required":["approver","evidence"],"properties":{"approver":{"type":"string","minLength":1,"description":"VID of the approver."},"evidence":{"\$ref":"#/\$defs/ApprovalEvidenceKind"},"recordedAt":{"type":"string","format":"date-time"}}},"ApprovalEvidenceKind":{"title":"ApprovalEvidenceKind","type":"string","enum":["didSigned","webauthn","approverSigned"],"description":"The evidence an approval was recorded on, as `auth/step-up/approve-response` names it. Only the approver\'s own evidence is ever recorded: a proof by a key the VTA records as acting for an approver — a console signing key or any other delegation — is never an approval (CONVENTIONS.md §6.3)."},"RotationState":{"title":"RotationState","type":"string","enum":["pendingApproval","awaitingRecoveryProof","staged","overlapping","completed","aborted","expired"],"description":"`pendingApproval` — awaiting the approvals the VTA\'s policy requires; nothing is published. `awaitingRecoveryProof` — approved, and waiting for the recovery custodian\'s proof over the change; nothing is published. `staged` — successor published, not yet used. `overlapping` — successor active, predecessor `retiring`. `completed` — every predecessor retired, or the change is published and any overlap it began has ended. `aborted` — the successor was retired instead of the predecessor, or a revocation superseded the change. `expired` — the approvals or the recovery proof did not arrive before the preview expired; nothing was published."},"RotationKind":{"title":"RotationKind","type":"string","enum":["planned","compromise","addition","recovery"],"description":"`planned` — a successor was staged, activated, and the predecessor retired on the operator\'s schedule. `compromise` — a key was revoked and, where the role would otherwise be empty, replaced in the same change. `addition` — a key joined a role without anything leaving it. `recovery` — the identifier\'s update authority moved to the committed recovery key, because the VTA\'s own update keys were lost or may be in someone else\'s hands."},"KeyRole":{"title":"KeyRole","type":"string","enum":["attestation","operational","messaging","update","authenticator"],"description":"The named key role a key occupies in an identity (CONVENTIONS.md §2; VTI-KEY-070 onward). `attestation` — the only keys in `assertionMethod`; sign the identity\'s attestation artefacts (credentials, endorsements, status lists) through the VTA\'s signing service and nowhere else. Generated inside the VTA, never derived, never exportable, never in a backup. `operational` — the only keys the identity\'s own process uses in `authentication`; sign the node\'s own traffic (Trust Task requests and responses, DIDComm and TSP signatures, invitations, notices, audit checkpoints). Derived. `messaging` — the only keys in `keyAgreement`; sign nothing. X25519, derived or generated in its own right and never converted from a signing key. `update` — the identifier\'s change authority as its DID method states it (a did:webvh log\'s `updateKeys` and `nextKeyHashes`, a KERI key event log\'s current and next keys); never a role-bound verification method, never in `keyRoles`. Generated inside the VTA, never derived, never exportable, never in a backup, and always accompanied by a committed recovery key held outside the VTA\'s protection boundary. `authenticator` — a key held on a person\'s own authenticator (a WebAuthn passkey), listed in `authentication` of that person\'s identity only; used only to verify the person\'s WebAuthn assertions (sign-in and step-up evidence) and never to accept a Data Integrity proof. The VTA never holds its private half, so it is enrolled by the passkey ceremony and never generated, added or rotated by these tasks. Never permitted on the durable identity of a VTA, a VTC or a VTN. No role permits `capabilityInvocation` or `capabilityDelegation` (VTI-KEY-075). The set is an extensible registry: a consumer that meets a role it does not implement MUST rely on the key for nothing, and MUST NOT map it onto a role it does know (VTI-KEY-074)."},"RoleKey":{"title":"RoleKey","type":"object","additionalProperties":false,"required":["role","keyType","state"],"description":"One key in one role. A key is in exactly one role for its whole life; a change of role is a retirement from one and an addition to another, with fresh material under a fresh identifier.","properties":{"verificationMethod":{"type":"string","minLength":1,"description":"The full verification-method identifier (`did#fragment`) the document publishes the key under and lists in `keyRoles`. Absent for `update` keys, which are never role-bound verification methods (VTI-KEY-093). A VTA minting a method SHOULD derive its fragment from the key (VTI-KEY-150)."},"role":{"\$ref":"#/\$defs/KeyRole"},"updateKeyClass":{"\$ref":"#/\$defs/UpdateKeyClass"},"relationships":{"type":"array","items":{"\$ref":"#/\$defs/DidVerificationRelationship"},"uniqueItems":true,"description":"The relationships the key is (or, while `pending`, will be) listed in: always exactly its role\'s one relationship. Empty for `update`, `retired` and `revoked` keys."},"keyType":{"\$ref":"#/\$defs/KeyType"},"publicKeyMultibase":{"type":"string","minLength":1,"description":"The public half, multibase-encoded, exactly as published. Absent for a `committed` update key, whose public half the identifier has not yet revealed."},"commitment":{"type":"string","minLength":1,"description":"For a `committed` update key: the commitment the identifier publishes (a did:webvh `nextKeyHashes` entry, a KERI next-key digest), in the method\'s own encoding."},"state":{"\$ref":"#/\$defs/RoleKeyState"},"publishedInVersionId":{"type":"string","description":"The method\'s version identifier of the change that first published the key or its commitment (method-profiles/: a did:webvh `versionId`, a KERI event\'s sequence number and digest). Absent while `pending`."},"removedInVersionId":{"type":"string","description":"Version identifier of the change that retired or revoked the key."},"activatesAt":{"type":"string","format":"date-time","description":"For a `staged` key: when the VTA will begin using it — no earlier than the publishing change\'s cache horizon."},"retireAfter":{"type":"string","format":"date-time","description":"For a `retiring` key: the end of its overlap. Custody projection only."},"compromisedSince":{"type":"string","format":"date-time","description":"For a `revoked` key: the compromise time (VTI-KEY-121), published as the verification method\'s `revoked` value. Where it cannot be established, the time the key was first published."},"rotationId":{"type":"string","description":"The rotation this key was introduced or retired by."},"label":{"type":"string","maxLength":256,"description":"Operator-facing label. Custody projection only."},"custody":{"\$ref":"#/\$defs/RoleKeyCustody"},"ext":{"\$ref":"#/\$defs/Ext"}}},"RoleKeyCustody":{"title":"RoleKeyCustody","type":"object","additionalProperties":false,"required":["exportable","neverExportable","inBackups","protection"],"description":"How a key is held. Present only in the custody projection. Carries no key material, and a conforming VTA MUST NOT place any in `ext`.","properties":{"keyId":{"type":"string","minLength":1,"description":"The custodian record identifier (`keys/*`\'s `keyId`) behind this key. Absent for a key this VTA does not hold (`protection: externalCustodian`)."},"origin":{"\$ref":"#/\$defs/KeyOrigin"},"exportable":{"type":"boolean","description":"Whether the custodian would release the private half. Always `false` for `attestation` and `update` keys. Stated explicitly, never absent."},"neverExportable":{"type":"boolean","description":"True when no authority can make the key exportable. `true` implies `exportable: false`."},"inBackups":{"type":"boolean","description":"Whether the key, or material it can be re-derived or decrypted from, is in the VTA\'s backups or any state transfer. Always `false` for `attestation` and `update` keys (VTI-KEY-112)."},"protection":{"\$ref":"#/\$defs/ProtectionClass"},"boundary":{"type":"string","minLength":1,"maxLength":128,"description":"Opaque, VTA-assigned label of the protection boundary holding the key (CONVENTIONS.md §5.2). Two keys with the same label are lost or compromised together. A recovery update key MUST carry a label different from every routine update key\'s. Custody projection only; never published."},"destroyed":{"type":"boolean","description":"True once the private half has been destroyed — a retired `attestation` or `messaging` key. The record survives so the key\'s past signatures stay attributable."}}},"ProtectionClass":{"title":"ProtectionClass","type":"string","enum":["software","encryptedAtRest","enclave","hardwareModule","externalCustodian"],"description":"How a private half is protected (CONVENTIONS.md §5.2). `software` — stored by the VTA without encryption independent of the host (a plain VTA). `encryptedAtRest` — wrapped under a key the VTA holds outside its store (a hardened VTA). `enclave` — held only inside an attested trusted execution environment, wrapped under a key released only to its measurement (a TEE VTA). `hardwareModule` — held by a hardware security module or cloud key service that performs the operation without releasing the key. `externalCustodian` — not held by this VTA at all: a recovery update key, or an `authenticator` key on a person\'s device."},"KeyOrigin":{"title":"KeyOrigin","type":"string","enum":["derived","imported","internal"],"description":"Where the private key came from. `derived` means the maintainer generated it from a seed it holds and can reproduce it from `derivationPath`; `imported` means it arrived from outside and exists only as stored material; `internal` means the maintainer generated it from a CSPRNG and it is reproducible from nothing at all. The distinction is operationally load-bearing: a `derived` key survives a seed restore, an `imported` one is lost unless it was backed up separately, and an `internal` one cannot be recovered by any means once the maintainer\'s storage is gone. This member is also the only way a consumer can confirm that a `keys/create` request for an `internal` key was honoured rather than silently downgraded to a derived one — see that specification\'s `internal` member.","default":"derived"},"RoleKeyState":{"title":"RoleKeyState","type":"string","enum":["pending","staged","active","retiring","retired","revoked","committed"],"description":"Where a key is in its role\'s lifecycle (CONVENTIONS.md §8, §10). `pending` — planned by a preview or a change awaiting approval; not published; custody projection only. `staged` — published and bound to its role but not yet used, until the publishing change\'s cache horizon. `active` — the key the VTA uses for new signatures (for `messaging`, advertises for new sessions; for `update`, the current authority). `retiring` — still published but never used to sign again; a retiring `messaging` key still decrypts until retirement. `retired` — removed by planned rotation; what it signed while published stays valid, judged against the identifier version current at issuance. `revoked` — withdrawn for compromise, recorded with `compromisedSince`; what it signed from then on establishes nothing. `committed` — an `update` key the identifier commits to as a successor but has not revealed (a did:webvh `nextKeyHashes` entry, a KERI next-key digest). `retired` and `revoked` are terminal."},"DidVerificationRelationship":{"title":"DidVerificationRelationship","type":"string","enum":["authentication","assertionMethod","keyAgreement","capabilityInvocation","capabilityDelegation"],"description":"A DID Core verification relationship."},"UpdateKeyClass":{"title":"UpdateKeyClass","type":"string","enum":["routine","recovery"],"description":"For an `update` key only (CONVENTIONS.md §5.3). `routine` — generated and held by the VTA, which authorizes the identity\'s ordinary changes with it. `recovery` — held by a recovery custodian in a protection boundary other than the VTA\'s; the VTA holds only its commitment, carries that commitment forward in every change it makes, and can use the key only by asking the custodian for a proof (`RecoverySigningRequest`)."},"KeyType":{"title":"KeyType","type":"string","enum":["ed25519","x25519","p256","mldsa44","mldsa65"],"description":"Cryptographic algorithm the key material belongs to. `ed25519` signs (EdDSA), `x25519` performs key agreement and never signs, `p256` signs (ES256), and `mldsa44` and `mldsa65` sign with the post-quantum ML-DSA scheme of US NIST FIPS 204. The set is expected to grow as algorithms are standardised, and growing it is a MINOR change under SPEC.md §5.2: `keyType` selects no schema branch, so adding a value relaxes a constraint rather than narrowing one, and the generated libraries mark this enumeration non-exhaustive so that a consumer absorbs a new value rather than failing to compile. Two ML-DSA parameter sets are carried because two specifications require different ones — W3C Quantum-Resistant Cryptosuites defines Data Integrity suites only for ML-DSA-44, while Trust Spanning Protocol Rev 3 §8.1 mandates ML-DSA-65 — so the parameter set is chosen by whatever consumes the key and the two are not redundant. A consumer that does not implement a value it receives MUST refuse the document rather than substitute one it does support."},"DidDocumentPreview":{"title":"DidDocumentPreview","type":"object","additionalProperties":false,"required":["previewId","method","expiresAt","changes","document","updateKeyRotates"],"description":"What a change would publish, computed by the VTA by running the handler it would run to apply it (CONVENTIONS.md §6.1). This is what a consent surface renders and what an approval is bound to.","properties":{"previewId":{"type":"string","minLength":16,"description":"Opaque, unguessable identifier of this exact plan. Carried back by the apply request; every approval and any recovery proof is bound to it."},"method":{"\$ref":"#/\$defs/DidMethodName"},"baseVersionId":{"type":"string","description":"The version identifier the plan was computed against. Absent only for a creation. The plan is void once the identifier moves past it."},"expiresAt":{"type":"string","format":"date-time"},"changes":{"type":"array","items":{"\$ref":"#/\$defs/DidDocumentChange"},"description":"Every change the plan would make, including the ones the caller did not ask for — in particular any movement of the update authority the method requires."},"document":{"type":"object","description":"The complete identifier document the change would publish, `keyRoles` included. Public data by construction."},"warnings":{"type":"array","items":{"\$ref":"#/\$defs/PreviewWarning"},"uniqueItems":true},"updateKeyRotates":{"type":"boolean","description":"True when applying the plan also moves the identifier\'s update authority to a committed successor — every change under did:webvh pre-rotation, never a KERI interaction event. Stated as its own member because it is the consequence a reviewer most often misses."},"recoverySigning":{"\$ref":"#/\$defs/RecoverySigningRequest"}}},"RecoverySigningRequest":{"title":"RecoverySigningRequest","type":"object","additionalProperties":false,"required":["commitment","keyType","unsignedChange","proofOptions"],"description":"What a recovery custodian must sign for a change that only the recovery key may authorize (CONVENTIONS.md §5.4, §9.4). The custodian MUST check `unsignedChange` itself — render it to its human, confirm that it reveals the recovery key it holds and commits to a fresh recovery key it also holds — and MUST NOT sign on the strength of this request\'s description alone.","properties":{"commitment":{"type":"string","minLength":1,"description":"The recovery commitment the identifier publishes; the custodian\'s key MUST be the one it commits to."},"keyType":{"\$ref":"#/\$defs/KeyType"},"unsignedChange":{"type":"string","minLength":1,"description":"The change exactly as it will be published, without the recovery proof, as JSON text in the method\'s own form (a did:webvh log entry, a KERI rotation event)."},"proofOptions":{"type":"object","description":"The proof the method requires over `unsignedChange`, without its signature value, as the method profile defines it (for did:webvh, a Data Integrity proof configuration with `proofPurpose: assertionMethod` and the recovery key\'s `did:key` as `verificationMethod`)."},"expiresAt":{"type":"string","format":"date-time"}}},"PreviewWarning":{"title":"PreviewWarning","type":"string","enum":["singleKeyRole","algorithmNotInAcceptedSet","roleWillHaveNoClassicalKey","attestationReissuanceRequired","selfPublish","noWitnesses","protectionBelowPolicy","recoveryKeyRevealed"],"description":"Conditions a human should be shown before approving. `singleKeyRole` — the role will hold one active key. `algorithmNotInAcceptedSet` — a verifier population the VTA knows of does not accept the new key\'s algorithm. `roleWillHaveNoClassicalKey` — every remaining key is post-quantum. `attestationReissuanceRequired` — revoking this attestation key obliges re-issuance and re-signed status lists (VTI-KEY-133). `selfPublish` — the VTA will not publish the change; the operator must. `noWitnesses` — the identifier has no witnesses, so a party holding the VTA\'s routine update key can drop the recovery commitment unobserved (CONVENTIONS.md §5.3). `protectionBelowPolicy` — a key will be held at a `ProtectionClass` below what the VTA\'s policy recommends for its role (a plain VTA holding an attestation key). `recoveryKeyRevealed` — this change uses the recovery key, which must be replaced by a fresh recovery commitment in the same change."},"DidDocumentChange":{"title":"DidDocumentChange","type":"object","additionalProperties":false,"required":["op","role"],"properties":{"op":{"type":"string","enum":["addKey","retireKey","revokeKey","rotateUpdateKey","commitUpdateKey","replaceRecoveryCommitment","useRecoveryKey"],"description":"`addKey` — a verification method joins its role\'s relationship and `keyRoles`. `retireKey` — a verification method leaves its relationship, `keyRoles` and the document. `revokeKey` — a verification method leaves its relationship and `keyRoles`, and stays in `verificationMethod` with `revoked` set to the compromise time (CONVENTIONS.md §9.1). `rotateUpdateKey` — the identifier\'s update authority moves to a committed routine successor. `commitUpdateKey` — a new routine successor is committed. `replaceRecoveryCommitment` — the recovery commitment changes. `useRecoveryKey` — the change is authorized by the recovery key, which the identifier then reveals."},"role":{"\$ref":"#/\$defs/KeyRole"},"verificationMethod":{"type":"string"},"keyType":{"\$ref":"#/\$defs/KeyType"},"publicKeyMultibase":{"type":"string"},"commitment":{"type":"string"},"relationships":{"type":"array","items":{"\$ref":"#/\$defs/DidVerificationRelationship"},"uniqueItems":true}}},"KeyRoleChangeOutcome":{"title":"KeyRoleChangeOutcome","type":"string","enum":["preview","applied","pendingApproval","awaitingRecoveryProof"],"description":"`preview` — nothing was written; the response carries the plan. `applied` — the change was made (and published, unless `publication.selfPublish`). `pendingApproval` — the plan is recorded and awaits further approvals. `awaitingRecoveryProof` — the plan is approved and waits for the recovery custodian\'s proof (`preview.recoverySigning`); nothing is published until it arrives."},"RecoveryCommitment":{"title":"RecoveryCommitment","type":"object","additionalProperties":false,"required":["keyType","publicKeyMultibase"],"description":"A recovery key offered for commitment (CONVENTIONS.md §5.3). The VTA computes the method\'s commitment from it, verifies `proofOfPossession`, and then keeps only the commitment. The key MUST be held by a custodian in a protection boundary other than the VTA\'s; a VTA MUST refuse one it generated or can derive (`vta/dids:recoveryCommitmentRequired`).","properties":{"keyType":{"\$ref":"#/\$defs/KeyType"},"publicKeyMultibase":{"type":"string","minLength":1,"description":"The recovery key\'s public half. Not published by the VTA where the method commits by hash."},"proofOfPossession":{"type":"string","minLength":1,"description":"Multibase signature by the recovery key over the UTF-8 bytes of `vta-dids-recovery-commitment/v1`, a zero byte, and the request\'s `previewId`. Absent on a dry run, which is how the `previewId` is obtained; REQUIRED on the apply request, and the only member besides `previewId`, `dryRun` and `recoveryProof` that may differ between the two."},"label":{"type":"string","maxLength":256,"description":"Operator-facing name of the custodian. Custody projection only; never published."}}}}}';

/// As [payloadSchemaJson], for the success-response variant.
const String responsePayloadSchemaJson =
    '{"\$schema":"https://json-schema.org/draft/2020-12/schema","\$ref":"#/\$defs/Response","\$defs":{"Response":{"\$anchor":"response","title":"VTA DIDs — Create — response payload","type":"object","additionalProperties":false,"required":["did","outcome"],"properties":{"did":{"type":"string","minLength":1},"outcome":{"\$ref":"#/\$defs/KeyRoleChangeOutcome"},"preview":{"\$ref":"#/\$defs/DidDocumentPreview","description":"Present when `outcome` is `preview`, `pendingApproval` or `awaitingRecoveryProof`: the plan, and what an approval is bound to."},"approvals":{"\$ref":"#/\$defs/KeyRoleApprovalState","description":"Present when `outcome` is `pendingApproval`."},"newVersionId":{"type":"string","description":"Present when `outcome` is `applied`: the version identifier of the change. Pass it as the next change\'s `expectedVersionId`."},"keys":{"type":"array","items":{"\$ref":"#/\$defs/RoleKey"},"description":"Every key whose state this change sets or would set, after the change."},"rotation":{"\$ref":"#/\$defs/RotationRecord"},"publication":{"\$ref":"#/\$defs/Publication","description":"Present when `outcome` is `applied`."},"contextId":{"type":"string"},"method":{"\$ref":"#/\$defs/DidMethodName"},"ext":{"\$ref":"#/\$defs/Ext"}}},"Ext":{"title":"Ext","description":"Vendor-namespaced extension object per SPEC.md §4.5.1. Each immediate key MUST be a reverse-DNS namespace; structure under each namespace is opaque to the framework.","type":"object","minProperties":1,"additionalProperties":true,"propertyNames":{"pattern":"^[a-z][a-z0-9-]*(\\\\.[a-z0-9-]+)+\$"}},"DidMethodName":{"title":"DidMethodName","type":"string","pattern":"^[a-z0-9]+(:[a-z0-9]+)*\$","description":"The DID method an identity uses, as the method profile that governs it is named: `webvh` for a did:webvh identity, `scid:vh` for the did:scid:vh:1 form of one, `webs` for did:webs. Deliberately a pattern and not an enumeration: a method is added by publishing its profile under method-profiles/, never by changing this schema. A VTA MUST refuse a method it holds no profile for, or whose profile declares it ineligible, with `vta/dids:methodNotEligible`."},"Publication":{"title":"Publication","type":"object","additionalProperties":false,"required":["selfPublish"],"description":"How the change reaches resolvers.","properties":{"selfPublish":{"type":"boolean","description":"True when no hosting service holds the identifier for the VTA: the caller must publish `artifacts`, and until it does resolvers see the previous version."},"artifacts":{"type":"array","items":{"\$ref":"#/\$defs/PublishedArtifact"},"description":"Present when `selfPublish` is true."}}},"PublishedArtifact":{"title":"PublishedArtifact","type":"object","additionalProperties":false,"required":["name","mediaType","content"],"description":"A file the identifier\'s method publishes, as the method profile names it (`did.jsonl` for did:webvh, `did.json` and `keri.cesr` for did:webs).","properties":{"name":{"type":"string","minLength":1,"maxLength":128},"mediaType":{"type":"string","minLength":1},"content":{"type":"string","description":"The artefact\'s content, or for an append-only artefact the appended part, as text."}}},"RotationRecord":{"title":"RotationRecord","type":"object","additionalProperties":false,"required":["rotationId","role","kind","state"],"description":"One change to a role\'s key set, from preview to completion. The identifier\'s history is the authority for what was published; this record adds which change was which and, in the custody projection, who asked, who approved, and why.","properties":{"rotationId":{"type":"string","minLength":1},"role":{"\$ref":"#/\$defs/KeyRole"},"kind":{"\$ref":"#/\$defs/RotationKind"},"state":{"\$ref":"#/\$defs/RotationState"},"predecessors":{"type":"array","items":{"type":"string"},"description":"Verification-method identifiers (for `update`, public keys or commitments) leaving the role."},"successors":{"type":"array","items":{"type":"string"},"description":"Verification-method identifiers (for `update`, public keys or commitments) entering the role."},"startedInVersionId":{"type":"string"},"endedInVersionId":{"type":"string"},"startedAt":{"type":"string","format":"date-time"},"cacheHorizonAt":{"type":"string","format":"date-time","description":"Planned rotations: the publishing change\'s cache horizon (CONVENTIONS.md §10.1). The switch and any retirement happen no earlier."},"activatesAt":{"type":"string","format":"date-time","description":"When the successor becomes `active` and the predecessor `retiring`; never before `cacheHorizonAt`."},"overlapUntil":{"type":"string","format":"date-time","description":"Custody projection only. End of the overlap."},"autoRetire":{"type":"boolean","description":"Custody projection only. Whether the VTA retires the predecessor itself at `overlapUntil`."},"endedAt":{"type":"string","format":"date-time"},"initiatedBy":{"type":"string","description":"Custody projection only. VID of the administrator whose signed request started the change."},"approvals":{"\$ref":"#/\$defs/KeyRoleApprovalState"},"reason":{"type":"string","maxLength":1024,"description":"Custody projection only. The operator\'s stated reason. Never published."},"ext":{"\$ref":"#/\$defs/Ext"}}},"KeyRoleApprovalState":{"title":"KeyRoleApprovalState","type":"object","additionalProperties":false,"required":["required","received","expiresAt"],"description":"Approval progress of a change the VTA\'s policy gates on approvals (CONVENTIONS.md §6).","properties":{"required":{"type":"integer","minimum":1,"description":"Distinct approvals the VTA\'s policy requires."},"received":{"type":"integer","minimum":0,"description":"Distinct approvals recorded so far, the initiator\'s own included."},"approvals":{"type":"array","items":{"\$ref":"#/\$defs/RecordedApproval"},"description":"The approvals recorded. Custody projection only; omitted from a response to anyone who is not themselves an eligible approver of this change."},"expiresAt":{"type":"string","format":"date-time","description":"When the preview, and every approval bound to it, stops being usable."}}},"RecordedApproval":{"title":"RecordedApproval","type":"object","additionalProperties":false,"required":["approver","evidence"],"properties":{"approver":{"type":"string","minLength":1,"description":"VID of the approver."},"evidence":{"\$ref":"#/\$defs/ApprovalEvidenceKind"},"recordedAt":{"type":"string","format":"date-time"}}},"ApprovalEvidenceKind":{"title":"ApprovalEvidenceKind","type":"string","enum":["didSigned","webauthn","approverSigned"],"description":"The evidence an approval was recorded on, as `auth/step-up/approve-response` names it. Only the approver\'s own evidence is ever recorded: a proof by a key the VTA records as acting for an approver — a console signing key or any other delegation — is never an approval (CONVENTIONS.md §6.3)."},"RotationState":{"title":"RotationState","type":"string","enum":["pendingApproval","awaitingRecoveryProof","staged","overlapping","completed","aborted","expired"],"description":"`pendingApproval` — awaiting the approvals the VTA\'s policy requires; nothing is published. `awaitingRecoveryProof` — approved, and waiting for the recovery custodian\'s proof over the change; nothing is published. `staged` — successor published, not yet used. `overlapping` — successor active, predecessor `retiring`. `completed` — every predecessor retired, or the change is published and any overlap it began has ended. `aborted` — the successor was retired instead of the predecessor, or a revocation superseded the change. `expired` — the approvals or the recovery proof did not arrive before the preview expired; nothing was published."},"RotationKind":{"title":"RotationKind","type":"string","enum":["planned","compromise","addition","recovery"],"description":"`planned` — a successor was staged, activated, and the predecessor retired on the operator\'s schedule. `compromise` — a key was revoked and, where the role would otherwise be empty, replaced in the same change. `addition` — a key joined a role without anything leaving it. `recovery` — the identifier\'s update authority moved to the committed recovery key, because the VTA\'s own update keys were lost or may be in someone else\'s hands."},"KeyRole":{"title":"KeyRole","type":"string","enum":["attestation","operational","messaging","update","authenticator"],"description":"The named key role a key occupies in an identity (CONVENTIONS.md §2; VTI-KEY-070 onward). `attestation` — the only keys in `assertionMethod`; sign the identity\'s attestation artefacts (credentials, endorsements, status lists) through the VTA\'s signing service and nowhere else. Generated inside the VTA, never derived, never exportable, never in a backup. `operational` — the only keys the identity\'s own process uses in `authentication`; sign the node\'s own traffic (Trust Task requests and responses, DIDComm and TSP signatures, invitations, notices, audit checkpoints). Derived. `messaging` — the only keys in `keyAgreement`; sign nothing. X25519, derived or generated in its own right and never converted from a signing key. `update` — the identifier\'s change authority as its DID method states it (a did:webvh log\'s `updateKeys` and `nextKeyHashes`, a KERI key event log\'s current and next keys); never a role-bound verification method, never in `keyRoles`. Generated inside the VTA, never derived, never exportable, never in a backup, and always accompanied by a committed recovery key held outside the VTA\'s protection boundary. `authenticator` — a key held on a person\'s own authenticator (a WebAuthn passkey), listed in `authentication` of that person\'s identity only; used only to verify the person\'s WebAuthn assertions (sign-in and step-up evidence) and never to accept a Data Integrity proof. The VTA never holds its private half, so it is enrolled by the passkey ceremony and never generated, added or rotated by these tasks. Never permitted on the durable identity of a VTA, a VTC or a VTN. No role permits `capabilityInvocation` or `capabilityDelegation` (VTI-KEY-075). The set is an extensible registry: a consumer that meets a role it does not implement MUST rely on the key for nothing, and MUST NOT map it onto a role it does know (VTI-KEY-074)."},"RoleKey":{"title":"RoleKey","type":"object","additionalProperties":false,"required":["role","keyType","state"],"description":"One key in one role. A key is in exactly one role for its whole life; a change of role is a retirement from one and an addition to another, with fresh material under a fresh identifier.","properties":{"verificationMethod":{"type":"string","minLength":1,"description":"The full verification-method identifier (`did#fragment`) the document publishes the key under and lists in `keyRoles`. Absent for `update` keys, which are never role-bound verification methods (VTI-KEY-093). A VTA minting a method SHOULD derive its fragment from the key (VTI-KEY-150)."},"role":{"\$ref":"#/\$defs/KeyRole"},"updateKeyClass":{"\$ref":"#/\$defs/UpdateKeyClass"},"relationships":{"type":"array","items":{"\$ref":"#/\$defs/DidVerificationRelationship"},"uniqueItems":true,"description":"The relationships the key is (or, while `pending`, will be) listed in: always exactly its role\'s one relationship. Empty for `update`, `retired` and `revoked` keys."},"keyType":{"\$ref":"#/\$defs/KeyType"},"publicKeyMultibase":{"type":"string","minLength":1,"description":"The public half, multibase-encoded, exactly as published. Absent for a `committed` update key, whose public half the identifier has not yet revealed."},"commitment":{"type":"string","minLength":1,"description":"For a `committed` update key: the commitment the identifier publishes (a did:webvh `nextKeyHashes` entry, a KERI next-key digest), in the method\'s own encoding."},"state":{"\$ref":"#/\$defs/RoleKeyState"},"publishedInVersionId":{"type":"string","description":"The method\'s version identifier of the change that first published the key or its commitment (method-profiles/: a did:webvh `versionId`, a KERI event\'s sequence number and digest). Absent while `pending`."},"removedInVersionId":{"type":"string","description":"Version identifier of the change that retired or revoked the key."},"activatesAt":{"type":"string","format":"date-time","description":"For a `staged` key: when the VTA will begin using it — no earlier than the publishing change\'s cache horizon."},"retireAfter":{"type":"string","format":"date-time","description":"For a `retiring` key: the end of its overlap. Custody projection only."},"compromisedSince":{"type":"string","format":"date-time","description":"For a `revoked` key: the compromise time (VTI-KEY-121), published as the verification method\'s `revoked` value. Where it cannot be established, the time the key was first published."},"rotationId":{"type":"string","description":"The rotation this key was introduced or retired by."},"label":{"type":"string","maxLength":256,"description":"Operator-facing label. Custody projection only."},"custody":{"\$ref":"#/\$defs/RoleKeyCustody"},"ext":{"\$ref":"#/\$defs/Ext"}}},"RoleKeyCustody":{"title":"RoleKeyCustody","type":"object","additionalProperties":false,"required":["exportable","neverExportable","inBackups","protection"],"description":"How a key is held. Present only in the custody projection. Carries no key material, and a conforming VTA MUST NOT place any in `ext`.","properties":{"keyId":{"type":"string","minLength":1,"description":"The custodian record identifier (`keys/*`\'s `keyId`) behind this key. Absent for a key this VTA does not hold (`protection: externalCustodian`)."},"origin":{"\$ref":"#/\$defs/KeyOrigin"},"exportable":{"type":"boolean","description":"Whether the custodian would release the private half. Always `false` for `attestation` and `update` keys. Stated explicitly, never absent."},"neverExportable":{"type":"boolean","description":"True when no authority can make the key exportable. `true` implies `exportable: false`."},"inBackups":{"type":"boolean","description":"Whether the key, or material it can be re-derived or decrypted from, is in the VTA\'s backups or any state transfer. Always `false` for `attestation` and `update` keys (VTI-KEY-112)."},"protection":{"\$ref":"#/\$defs/ProtectionClass"},"boundary":{"type":"string","minLength":1,"maxLength":128,"description":"Opaque, VTA-assigned label of the protection boundary holding the key (CONVENTIONS.md §5.2). Two keys with the same label are lost or compromised together. A recovery update key MUST carry a label different from every routine update key\'s. Custody projection only; never published."},"destroyed":{"type":"boolean","description":"True once the private half has been destroyed — a retired `attestation` or `messaging` key. The record survives so the key\'s past signatures stay attributable."}}},"ProtectionClass":{"title":"ProtectionClass","type":"string","enum":["software","encryptedAtRest","enclave","hardwareModule","externalCustodian"],"description":"How a private half is protected (CONVENTIONS.md §5.2). `software` — stored by the VTA without encryption independent of the host (a plain VTA). `encryptedAtRest` — wrapped under a key the VTA holds outside its store (a hardened VTA). `enclave` — held only inside an attested trusted execution environment, wrapped under a key released only to its measurement (a TEE VTA). `hardwareModule` — held by a hardware security module or cloud key service that performs the operation without releasing the key. `externalCustodian` — not held by this VTA at all: a recovery update key, or an `authenticator` key on a person\'s device."},"KeyOrigin":{"title":"KeyOrigin","type":"string","enum":["derived","imported","internal"],"description":"Where the private key came from. `derived` means the maintainer generated it from a seed it holds and can reproduce it from `derivationPath`; `imported` means it arrived from outside and exists only as stored material; `internal` means the maintainer generated it from a CSPRNG and it is reproducible from nothing at all. The distinction is operationally load-bearing: a `derived` key survives a seed restore, an `imported` one is lost unless it was backed up separately, and an `internal` one cannot be recovered by any means once the maintainer\'s storage is gone. This member is also the only way a consumer can confirm that a `keys/create` request for an `internal` key was honoured rather than silently downgraded to a derived one — see that specification\'s `internal` member.","default":"derived"},"RoleKeyState":{"title":"RoleKeyState","type":"string","enum":["pending","staged","active","retiring","retired","revoked","committed"],"description":"Where a key is in its role\'s lifecycle (CONVENTIONS.md §8, §10). `pending` — planned by a preview or a change awaiting approval; not published; custody projection only. `staged` — published and bound to its role but not yet used, until the publishing change\'s cache horizon. `active` — the key the VTA uses for new signatures (for `messaging`, advertises for new sessions; for `update`, the current authority). `retiring` — still published but never used to sign again; a retiring `messaging` key still decrypts until retirement. `retired` — removed by planned rotation; what it signed while published stays valid, judged against the identifier version current at issuance. `revoked` — withdrawn for compromise, recorded with `compromisedSince`; what it signed from then on establishes nothing. `committed` — an `update` key the identifier commits to as a successor but has not revealed (a did:webvh `nextKeyHashes` entry, a KERI next-key digest). `retired` and `revoked` are terminal."},"DidVerificationRelationship":{"title":"DidVerificationRelationship","type":"string","enum":["authentication","assertionMethod","keyAgreement","capabilityInvocation","capabilityDelegation"],"description":"A DID Core verification relationship."},"UpdateKeyClass":{"title":"UpdateKeyClass","type":"string","enum":["routine","recovery"],"description":"For an `update` key only (CONVENTIONS.md §5.3). `routine` — generated and held by the VTA, which authorizes the identity\'s ordinary changes with it. `recovery` — held by a recovery custodian in a protection boundary other than the VTA\'s; the VTA holds only its commitment, carries that commitment forward in every change it makes, and can use the key only by asking the custodian for a proof (`RecoverySigningRequest`)."},"KeyType":{"title":"KeyType","type":"string","enum":["ed25519","x25519","p256","mldsa44","mldsa65"],"description":"Cryptographic algorithm the key material belongs to. `ed25519` signs (EdDSA), `x25519` performs key agreement and never signs, `p256` signs (ES256), and `mldsa44` and `mldsa65` sign with the post-quantum ML-DSA scheme of US NIST FIPS 204. The set is expected to grow as algorithms are standardised, and growing it is a MINOR change under SPEC.md §5.2: `keyType` selects no schema branch, so adding a value relaxes a constraint rather than narrowing one, and the generated libraries mark this enumeration non-exhaustive so that a consumer absorbs a new value rather than failing to compile. Two ML-DSA parameter sets are carried because two specifications require different ones — W3C Quantum-Resistant Cryptosuites defines Data Integrity suites only for ML-DSA-44, while Trust Spanning Protocol Rev 3 §8.1 mandates ML-DSA-65 — so the parameter set is chosen by whatever consumes the key and the two are not redundant. A consumer that does not implement a value it receives MUST refuse the document rather than substitute one it does support."},"DidDocumentPreview":{"title":"DidDocumentPreview","type":"object","additionalProperties":false,"required":["previewId","method","expiresAt","changes","document","updateKeyRotates"],"description":"What a change would publish, computed by the VTA by running the handler it would run to apply it (CONVENTIONS.md §6.1). This is what a consent surface renders and what an approval is bound to.","properties":{"previewId":{"type":"string","minLength":16,"description":"Opaque, unguessable identifier of this exact plan. Carried back by the apply request; every approval and any recovery proof is bound to it."},"method":{"\$ref":"#/\$defs/DidMethodName"},"baseVersionId":{"type":"string","description":"The version identifier the plan was computed against. Absent only for a creation. The plan is void once the identifier moves past it."},"expiresAt":{"type":"string","format":"date-time"},"changes":{"type":"array","items":{"\$ref":"#/\$defs/DidDocumentChange"},"description":"Every change the plan would make, including the ones the caller did not ask for — in particular any movement of the update authority the method requires."},"document":{"type":"object","description":"The complete identifier document the change would publish, `keyRoles` included. Public data by construction."},"warnings":{"type":"array","items":{"\$ref":"#/\$defs/PreviewWarning"},"uniqueItems":true},"updateKeyRotates":{"type":"boolean","description":"True when applying the plan also moves the identifier\'s update authority to a committed successor — every change under did:webvh pre-rotation, never a KERI interaction event. Stated as its own member because it is the consequence a reviewer most often misses."},"recoverySigning":{"\$ref":"#/\$defs/RecoverySigningRequest"}}},"RecoverySigningRequest":{"title":"RecoverySigningRequest","type":"object","additionalProperties":false,"required":["commitment","keyType","unsignedChange","proofOptions"],"description":"What a recovery custodian must sign for a change that only the recovery key may authorize (CONVENTIONS.md §5.4, §9.4). The custodian MUST check `unsignedChange` itself — render it to its human, confirm that it reveals the recovery key it holds and commits to a fresh recovery key it also holds — and MUST NOT sign on the strength of this request\'s description alone.","properties":{"commitment":{"type":"string","minLength":1,"description":"The recovery commitment the identifier publishes; the custodian\'s key MUST be the one it commits to."},"keyType":{"\$ref":"#/\$defs/KeyType"},"unsignedChange":{"type":"string","minLength":1,"description":"The change exactly as it will be published, without the recovery proof, as JSON text in the method\'s own form (a did:webvh log entry, a KERI rotation event)."},"proofOptions":{"type":"object","description":"The proof the method requires over `unsignedChange`, without its signature value, as the method profile defines it (for did:webvh, a Data Integrity proof configuration with `proofPurpose: assertionMethod` and the recovery key\'s `did:key` as `verificationMethod`)."},"expiresAt":{"type":"string","format":"date-time"}}},"PreviewWarning":{"title":"PreviewWarning","type":"string","enum":["singleKeyRole","algorithmNotInAcceptedSet","roleWillHaveNoClassicalKey","attestationReissuanceRequired","selfPublish","noWitnesses","protectionBelowPolicy","recoveryKeyRevealed"],"description":"Conditions a human should be shown before approving. `singleKeyRole` — the role will hold one active key. `algorithmNotInAcceptedSet` — a verifier population the VTA knows of does not accept the new key\'s algorithm. `roleWillHaveNoClassicalKey` — every remaining key is post-quantum. `attestationReissuanceRequired` — revoking this attestation key obliges re-issuance and re-signed status lists (VTI-KEY-133). `selfPublish` — the VTA will not publish the change; the operator must. `noWitnesses` — the identifier has no witnesses, so a party holding the VTA\'s routine update key can drop the recovery commitment unobserved (CONVENTIONS.md §5.3). `protectionBelowPolicy` — a key will be held at a `ProtectionClass` below what the VTA\'s policy recommends for its role (a plain VTA holding an attestation key). `recoveryKeyRevealed` — this change uses the recovery key, which must be replaced by a fresh recovery commitment in the same change."},"DidDocumentChange":{"title":"DidDocumentChange","type":"object","additionalProperties":false,"required":["op","role"],"properties":{"op":{"type":"string","enum":["addKey","retireKey","revokeKey","rotateUpdateKey","commitUpdateKey","replaceRecoveryCommitment","useRecoveryKey"],"description":"`addKey` — a verification method joins its role\'s relationship and `keyRoles`. `retireKey` — a verification method leaves its relationship, `keyRoles` and the document. `revokeKey` — a verification method leaves its relationship and `keyRoles`, and stays in `verificationMethod` with `revoked` set to the compromise time (CONVENTIONS.md §9.1). `rotateUpdateKey` — the identifier\'s update authority moves to a committed routine successor. `commitUpdateKey` — a new routine successor is committed. `replaceRecoveryCommitment` — the recovery commitment changes. `useRecoveryKey` — the change is authorized by the recovery key, which the identifier then reveals."},"role":{"\$ref":"#/\$defs/KeyRole"},"verificationMethod":{"type":"string"},"keyType":{"\$ref":"#/\$defs/KeyType"},"publicKeyMultibase":{"type":"string"},"commitment":{"type":"string"},"relationships":{"type":"array","items":{"\$ref":"#/\$defs/DidVerificationRelationship"},"uniqueItems":true}}},"KeyRoleChangeOutcome":{"title":"KeyRoleChangeOutcome","type":"string","enum":["preview","applied","pendingApproval","awaitingRecoveryProof"],"description":"`preview` — nothing was written; the response carries the plan. `applied` — the change was made (and published, unless `publication.selfPublish`). `pendingApproval` — the plan is recorded and awaits further approvals. `awaitingRecoveryProof` — the plan is approved and waits for the recovery custodian\'s proof (`preview.recoverySigning`); nothing is published until it arrives."},"RecoveryCommitment":{"title":"RecoveryCommitment","type":"object","additionalProperties":false,"required":["keyType","publicKeyMultibase"],"description":"A recovery key offered for commitment (CONVENTIONS.md §5.3). The VTA computes the method\'s commitment from it, verifies `proofOfPossession`, and then keeps only the commitment. The key MUST be held by a custodian in a protection boundary other than the VTA\'s; a VTA MUST refuse one it generated or can derive (`vta/dids:recoveryCommitmentRequired`).","properties":{"keyType":{"\$ref":"#/\$defs/KeyType"},"publicKeyMultibase":{"type":"string","minLength":1,"description":"The recovery key\'s public half. Not published by the VTA where the method commits by hash."},"proofOfPossession":{"type":"string","minLength":1,"description":"Multibase signature by the recovery key over the UTF-8 bytes of `vta-dids-recovery-commitment/v1`, a zero byte, and the request\'s `previewId`. Absent on a dry run, which is how the `previewId` is obtained; REQUIRED on the apply request, and the only member besides `previewId`, `dryRun` and `recoveryProof` that may differ between the two."},"label":{"type":"string","maxLength":256,"description":"Operator-facing name of the custodian. Custody projection only; never published."}}}}}';

/// The SPEC §7.2 policy for the request variant, taken from this
/// specification's front matter.
///
/// Pass it to [consumeInbound] — items 5b, 7 and 8 are per-specification and
/// cannot be derived from the document alone, and item 2 needs the schema it
/// carries.
const SpecPolicy spec = SpecPolicy(
  typeUri: typeUri,
  isBearer: false,
  isProofRequired: true,
  isRecipientRequired: true,
  isIssuedAtRequired: true,
  payloadSchema: payloadSchemaJson,
);

/// The SPEC §7.2 policy for the success-response variant.
///
/// `isRecipientRequired` tracks the *issuer* party's requirement, because a
/// response swaps the parties (§7.3 item 5).
const SpecPolicy responseSpec = SpecPolicy(
  typeUri: responseTypeUri,
  isBearer: false,
  isProofRequired: true,
  isRecipientRequired: true,
  isIssuedAtRequired: true,
  payloadSchema: responsePayloadSchemaJson,
);
